CREATE DATABASE CallingBell;
GO
USE CallingBell;
GO
CREATE TABLE Categories(Id BIGINT IDENTITY PRIMARY KEY,Name NVARCHAR(150) NOT NULL,Icon NVARCHAR(200),BusinessCount INT NOT NULL DEFAULT 0,IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE Businesses(Id BIGINT IDENTITY PRIMARY KEY,Name NVARCHAR(200) NOT NULL,Category NVARCHAR(150) NOT NULL,ImageUrl NVARCHAR(1000),Rating DECIMAL(3,2) NOT NULL DEFAULT 0,ReviewCount INT NOT NULL DEFAULT 0,DistanceKm DECIMAL(8,2) NOT NULL DEFAULT 0,IsVerified BIT NOT NULL DEFAULT 0,IsSponsored BIT NOT NULL DEFAULT 0,Address NVARCHAR(500),IsActive BIT NOT NULL DEFAULT 1);
CREATE INDEX IX_Businesses_Category ON Businesses(Category); CREATE INDEX IX_Businesses_Rating ON Businesses(Rating);
CREATE TABLE TrendingServices(Id BIGINT IDENTITY PRIMARY KEY,Name NVARCHAR(150) NOT NULL,Searches INT NOT NULL DEFAULT 0,ImageUrl NVARCHAR(1000),IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE NearbyBusinesses(Id BIGINT IDENTITY PRIMARY KEY,Name NVARCHAR(200) NOT NULL,Category NVARCHAR(150) NOT NULL,DistanceKm DECIMAL(8,2) NOT NULL);
CREATE TABLE Banners(Id BIGINT IDENTITY PRIMARY KEY,Title NVARCHAR(250) NOT NULL,Subtitle NVARCHAR(500),ImageUrl NVARCHAR(1000),CtaText NVARCHAR(80) NOT NULL DEFAULT 'Search',IsActive BIT NOT NULL DEFAULT 1);
